CREATE MASKING POLICY IF NOT EXISTS SEC.MP_CREDIT_SCORE AS (v NUMBER) RETURNS NUMBER -> v
  COMMENT = 'Credit score is masked for all roles except Finance and Credit Risk teams.. Cognos masked value ''*** Restricted ***'' cannot be returned for a NUMBER column; NULL is returned';

ALTER MASKING POLICY SEC.MP_CREDIT_SCORE SET BODY ->
    CASE
    WHEN CONTAINS(',' || COALESCE(SYSTEM$GET_TAG_ON_CURRENT_COLUMN('GOV.ABAC_POLICY'), '') || ',', ',REGULATORY_SENSITIVE_DATA,') AND NOT (IS_ROLE_IN_SESSION('COMPLIANCE_OFFICERS') OR IS_ROLE_IN_SESSION('NERC_AUDITORS') OR IS_ROLE_IN_SESSION('REPORT_ADMINS')) THEN NULL
    WHEN CONTAINS(',' || COALESCE(SYSTEM$GET_TAG_ON_CURRENT_COLUMN('GOV.ABAC_POLICY'), '') || ',', ',SENSITIVE_DATA_POLICY,') AND COALESCE((SELECT MAX(a.ATTRIBUTE_VALUE) FROM SEC.MAP_USER_ATTRIBUTE a WHERE a.USERNAME = CURRENT_USER() AND a.ATTRIBUTE_NAME = 'dataClassification'), '') = 'restricted' THEN NULL
    WHEN CONTAINS(',' || COALESCE(SYSTEM$GET_TAG_ON_CURRENT_COLUMN('GOV.ABAC_POLICY'), '') || ',', ',SENSITIVE_FINANCIAL_DATA,') AND (COALESCE((SELECT MAX(a.ATTRIBUTE_VALUE) FROM SEC.MAP_USER_ATTRIBUTE a WHERE a.USERNAME = CURRENT_USER() AND a.ATTRIBUTE_NAME = 'dataClassification'), '') <> 'restricted' AND COALESCE((SELECT MAX(a.ATTRIBUTE_VALUE) FROM SEC.MAP_USER_ATTRIBUTE a WHERE a.USERNAME = CURRENT_USER() AND a.ATTRIBUTE_NAME = 'dataClassification'), '') <> 'confidential') THEN NULL
    WHEN IS_ROLE_IN_SESSION('BILLING_ANALYSTS') OR IS_ROLE_IN_SESSION('COMPLIANCE_OFFICERS') OR IS_ROLE_IN_SESSION('FIELD_TECHNICIANS') OR IS_ROLE_IN_SESSION('OPERATIONS_VIEWERS') THEN NULL
    WHEN IS_ROLE_IN_SESSION('CREDIT_RISK_TEAM') OR IS_ROLE_IN_SESSION('FINANCE_ANALYSTS') OR IS_ROLE_IN_SESSION('FINANCE_MANAGERS') OR IS_ROLE_IN_SESSION('REPORT_ADMINS') THEN v
    ELSE NULL
    END;

ALTER MASKING POLICY SEC.MP_CREDIT_SCORE SET COMMENT = 'Credit score is masked for all roles except Finance and Credit Risk teams.. Cognos masked value ''*** Restricted ***'' cannot be returned for a NUMBER column; NULL is returned';
